<?php

namespace App\Models;

use App\Enums\CheckInResult;
use Carbon\CarbonInterface;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;

/**
 * One scan at the gate, successful or not, attributed to the individual
 * staff member who made it. scanner_request_id is generated by the scanner
 * per scan, so a network retry of the same scan is recognised and answered
 * with the original result instead of being processed twice.
 *
 * @property int $id
 * @property int|null $ticket_id
 * @property int $event_id
 * @property int $staff_user_id
 * @property string $scanner_request_id
 * @property CheckInResult $result
 * @property CarbonInterface $scanned_at
 * @property string|null $device_label
 * @property CarbonInterface|null $created_at
 * @property CarbonInterface|null $updated_at
 */
class CheckIn extends Model
{
    /**
     * @return array<string, string>
     */
    protected function casts(): array
    {
        return [
            'result' => CheckInResult::class,
            'scanned_at' => 'datetime',
        ];
    }

    /**
     * @return BelongsTo<Ticket, $this>
     */
    public function ticket(): BelongsTo
    {
        return $this->belongsTo(Ticket::class);
    }

    /**
     * @return BelongsTo<Event, $this>
     */
    public function event(): BelongsTo
    {
        return $this->belongsTo(Event::class);
    }

    /**
     * @return BelongsTo<User, $this>
     */
    public function staff(): BelongsTo
    {
        return $this->belongsTo(User::class, 'staff_user_id');
    }
}
